        if re.search(pat, t, re.I):
            return name
    return None


def norm(s):
    return re.sub(r"[^a-z0-9]", "", str(s or "").lower())


def norm_words(s):
    """Lowercase, keep word boundaries as single spaces (for whole-word searches)."""
    return " ".join(re.findall(r"[a-z0-9]+", str(s or "").lower()))


def norm_vendor(s):
    s = re.sub(r"\b(ltd|limited|co|company|pvt|private|inc|corp|llc|the|bd|bangladesh|asia)\b", " ", str(s or "").lower())
    return norm(s)


def blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")


def num(v):
    try:
        return float(str(v).replace(",", "").strip())
    except Exception:
        return None


def letters(s):
    return re.sub(r"[^A-Z]", "", str(s or "").upper())


def subseq(short, long_):
    it = iter(long_)
    return all(ch in it for ch in short)


def colour_match(a, b):
    """BLACKWASH ~ BLACK 07 ~ BLKWASH, NAVY ~ NAVY 08, Ivory ~ IVORY."""
    a, b = letters(a), letters(b)
    if not a or not b:
        return False
    if a == b:
        return True
    s, l_ = (a, b) if len(a) <= len(b) else (b, a)
    if len(s) >= 3 and l_.startswith(s):
        return True
    return len(s) >= 4 and s[0] == l_[0] and subseq(s, l_)


def colour_score(a, b):
    """How well garment colour a fits PO/CBD colour label b. 0 = no match; exact name wins over prefix/abbreviation."""
    if not colour_match(a, b):
        return 0
    la, lb = letters(a), letters(b)
    if la == lb:
        return 1000
    pre = 0
    for x, y in zip(la, lb):
        if x != y:
            break
        pre += 1
    return pre + 1


def best_owner(label, garments):
    """The single garment colour a PO colour label belongs to, or None if none / a tie."""
    sc = sorted(((colour_score(g, label), g) for g in garments), reverse=True)
    sc = [x for x in sc if x[0] > 0]
    if not sc or (len(sc) > 1 and sc[0][0] == sc[1][0]):
        return None
    return sc[0][1]


def close(a, b, tol=0.005):
    a, b = num(a), num(b)
    return a is not None and b is not None and abs(a - b) <= tol * max(abs(b), 1e-9)


def first_line(v):
    return str(v or "").split("\n")[0].strip()


LEN_RE = re.compile(r"\b\d+\s*CM\b")

# ======================================================================== PO PDF
SUB_REST = re.compile(r"^\s*(.*?)\s*([\d,]+\.\d{2,3})([A-Z][A-Za-z0-9().]*)\s+([\d.]+)\s+([\d,]+\.\d+)$")
HEADER_SKIP = ("Printed", "Page ", "Print ", "Purchase Order", "Tel:", "Tel :", "Fax:", "E-mail", "Email")


def parse_po(path):
    """Read every PO, item and line. Item AND line numbers are glued to the text in this PDF format
    ("124L Plastic Button" = item 1 '24L ...', "130X29 ..." = line 1 '30X29'), so both are read with counters."""
    pos, cur, item, in_items = [], None, None, False
    warnings = []
    n = lambda s: float(s.replace(",", ""))
    header_lines = set()
    with pdfplumber.open(path) as pdf:
        for pno, page in enumerate(pdf.pages, 1):
            text = page.extract_text() or ""
            if not text.strip() and getattr(page, "images", None):
                warnings.append(f"PDF page {pno} has no readable text but contains an image (scanned page?). "
                                "Any PO on it was NOT read.")
            lines = text.splitlines()
            sup_idx = next((i for i, l in enumerate(lines) if l.strip().startswith("Supplier")), None)
            for i, ln in enumerate(lines):
                ln = ln.strip()
                if re.match(r"Supplier\s*:", ln):
                    m = re.search(r"PO No\.?\s*:\s*(\d+)", ln)
                    po_no = m.group(1) if m else "?"
                    if cur is not None and po_no == cur["po_no"]:
                        continue                      # same PO repeated its header on a new page
                    nxt = lines[i + 1] if i + 1 < len(lines) else ""
                    cur = {"po_no": po_no, "page": pno, "supplier": re.split(r"\s+PO Date\s*:", nxt)[0].strip(),
                           "type": "", "currency": "", "file_no": "", "items": [], "grand": None}
                    pos.append(cur)
                    in_items, item = False, None
                    header_lines |= {l.strip() for l in lines[:i]}
                    continue
                if cur is None:
                    continue
                if not cur["type"]:
                    m = re.search(r"\bType\s*:\s*(Local\s+PO|Direct|Normal|Import)\b", ln, re.I)
                    if m:
                        t = re.sub(r"\s+", " ", m.group(1)).title()
                        cur["type"] = "Local PO" if t.lower() == "local po" else t
                if not cur["currency"]:
                    m = re.search(r"Currency\s*:\s*([A-Z]{3})", ln)
                    cur["currency"] = m.group(1) if m else ""
                if not cur["file_no"]:
                    m = re.search(r"File No\.?\s*:\s*(\S+)", ln)
                    cur["file_no"] = m.group(1) if m else ""
                if re.match(r"Sl\.?\s*No", ln, re.I):
                    in_items = True
                    continue
                if not in_items:
                    continue
                if ln in header_lines or ln.startswith(HEADER_SKIP):
                    continue                          # repeated page header on a continuation page
                if ln.startswith("Grand Total"):
                    m = re.match(r"Grand Total\s+([\d,]+\.\d+)\S*\s+([\d,]+\.\d+)", ln)
                    cur["grand"] = (n(m.group(1)), n(m.group(2))) if m else None
                    in_items, item = False, None
                    continue
                if ln.startswith("Sub Total"):
                    m = re.match(r"Sub Total\s+([\d,]+\.\d+)\S*\s+([\d,]+\.\d+)", ln)
                    if item and m:
                        item["sub"] = (n(m.group(1)), n(m.group(2)))
                    continue
                handled = False
                for key, fld in (("Our Ref", "ref"), ("HS Code", "hs"), ("Delivery Date", "delivery")):
                    if re.match(rf"{key}\s*:", ln) and item:
                        item[fld] = ln.split(":", 1)[1].strip()
                        if fld == "ref":
                            item["ref_seen"] = True
                        handled = True
                if handled:
                    continue
                if item and item.get("ref_seen"):
                    lexp = str(len(item["lines"]) + 1)
                    if ln.startswith(lexp):
                        sm = SUB_REST.match(ln[len(lexp):])
                        if sm:
                            item["lines"].append({"no": int(lexp), "spec": sm.group(1).strip(), "qty": n(sm.group(2)),
                                                  "uom": sm.group(3), "price": float(sm.group(4)), "amount": n(sm.group(5)),
                                                  "page": pno})
                            continue
                exp = str(len(cur["items"]) + 1)
                if ln.startswith(exp) and (item is None or item.get("ref_seen")):
                    item = {"item_no": int(exp), "desc": ln[len(exp):].strip(), "ref": "", "hs": "", "delivery": "",
                            "lines": [], "sub": None, "po": cur, "ref_seen": False}
                    cur["items"].append(item)
                elif item and not item.get("ref_seen"):
                    item["desc"] += " " + ln
    items = [it for po in pos for it in po["items"]]
    for it in items:
        it["cat"] = categorize(it["desc"])
        if it["cat"] is None and it["lines"] and it["lines"][0]["uom"].upper().startswith("YD"):
            it["cat"] = "fabric"
        it["key"] = f"{it['po']['po_no']}-{it['item_no']}"
        if not it["po"]["type"]:
            pass
    for po in pos:
        if not po["type"]:
            warnings.append(f"PO {po['po_no']}: PO type (Local PO / Direct / Normal) not found")
        if not po["supplier"]:
            warnings.append(f"PO {po['po_no']}: supplier name not found")
    return pos, items, warnings


def po_checks(pos):
    rows, ok_all = [], True
    for po in pos:
        for it in po["items"]:
            q = sum(l["qty"] for l in it["lines"])
            a = sum(l["amount"] for l in it["lines"])
            bad_lines = [l for l in it["lines"] if l["qty"] and abs(round(l["amount"] / l["qty"], 5) - l["price"]) > 1e-5
                         and abs(l["qty"] * l["price"] - l["amount"]) > 0.011]
            ok = bool(it["lines"]) and it["sub"] is not None and abs(q - it["sub"][0]) < 0.01 and abs(a - it["sub"][1]) < 0.011 and not bad_lines
            ok_all &= ok
            rows.append([po["po_no"], po["page"], po["supplier"], f"item {it['item_no']}", it["desc"][:70],
                         len(it["lines"]), it["sub"][0] if it["sub"] else None, round(q, 2), it["sub"][1] if it["sub"] else None,
                         round(a, 4), "OK" if ok else "FAIL"])
        gq = sum(l["qty"] for it in po["items"] for l in it["lines"])
        ga = sum(l["amount"] for it in po["items"] for l in it["lines"])
        ok = po["grand"] is not None and abs(gq - po["grand"][0]) < 0.01 and abs(ga - po["grand"][1]) < 0.011
        ok_all &= ok
        rows.append([po["po_no"], po["page"], po["supplier"], "GRAND TOTAL", "", "", po["grand"][0] if po["grand"] else None,
                     round(gq, 2), po["grand"][1] if po["grand"] else None, round(ga, 4), "OK" if ok else "FAIL"])
    return rows, ok_all


def spec_colour(spec):
    """'BLACK 07 30X29' -> 'BLACK 07'; 'IVORY SIZE 10' -> 'IVORY'; '30X29' -> None."""
    toks = spec.split()
    words, i = [], 0
    stop = {"SIZE", "CM", "MM", "X", "XS", "S", "M", "L", "XL", "XXL", "XXXL", "ONE", "PCS", "YDS", "YD"}
    while i < len(toks) and re.fullmatch(r"[A-Z][A-Z/&-]+", toks[i]) and toks[i] not in stop:
        words.append(toks[i])
        i += 1
    if words and i < len(toks) and re.fullmatch(r"\d{2}", toks[i]):
        words.append(toks[i])
    return " ".join(words) or None


def po_code(it):
    d = it["desc"]
    if it["cat"] == "fabric":
        m = re.search(r"#?([A-Z0-9]+(?:-[A-Z0-9]+){2,})", d)
        return ("#" + m.group(1)) if m and d.lstrip().startswith("#") else (m.group(1) if m else None)
    if it["cat"] == "thread":
        m = re.search(r"\bTex[- ]?(\d+)", d, re.I)
        if m:
            return f"Tex {m.group(1)}"
        m = re.search(r"\bT-(\d+)\b", d)
        return f"T-{m.group(1)}" if m else None
    if it["cat"] == "zipper":
        m = re.search(r"\bNO\.\s?(\d+)\b", d)
        return f"NO.{m.group(1)}" if m else None
    m = re.match(r"\s*([A-Z]{2,}(?:-[A-Z0-9]+)+)\b", d)              # DUN-MSS, DUN-RF-EUWALEG
    if m:
        return m.group(1)
    if it["cat"] in TYPE_NUMBER_CATS:
        t = type_number(d)
        if t is not None:
            return t
    m = re.search(r"-\s*([A-Z]{2,}[A-Z0-9]*\d[A-Z0-9]*)\b", d)        # Main Label- GALPETML1
    return m.group(1) if m else None


def type_number(text):
    t = str(text or "")
    m = re.match(r"\s*(\d{1,3})\s+[A-Za-z]", t)                         # "25 DUNNESA0 ..."
    if m:
        return int(m.group(1))
    ms = re.findall(r"(?:-|Type)\s*(\d{1,3})\b(?!\s*(?:cm|mm|\"|%))", t, re.I)   # "Barcode Tag- 07", "- 28", "Type 7"
    return int(ms[0]) if ms else None


def size_tokens(text):
    """Comparable size tokens: ('cm', 47.0), ('L', 28), ('in', 1), ('mm', '15x40')."""
    t = str(text or "")
    out = set()
    for m in re.finditer(r"(\d+(?:\.\d+)?)\s*cm\b", t, re.I):
        out.add(("cm", float(m.group(1))))
    for m in re.finditer(r"\b(\d{2})\s*L\b", t):
        out.add(("L", int(m.group(1))))
    for m in re.finditer(r"(?<![\d.])(\d)\s*[\"”]\s*(?!CW|W\b|X|L\b)", t):
        out.add(("in", int(m.group(1))))
    return out


def po_size(it, lines=None):
    d = it["desc"]
    m = re.search(r"\((\d+(?:\.\d+)?\s*mm\s*x\s*\d+(?:\.\d+)?\s*mm)\)", d, re.I)
    if m:
        return re.sub(r"\s+", " ", m.group(1))
    m = re.search(r"\b(L-\d+\s*cm\s*x\s*W-\d+\s*cm)", d, re.I)
    if m:
        return m.group(1)
    if it["cat"] == "fabric":
        m = re.search(r"(\d{2,3})\s*[\"”]\s*CW", d, re.I)
        return f'{m.group(1)}"CW' if m else None
    if it["cat"] == "button":
        m = re.search(r"\b(\d{2}L)\b", d)
        return m.group(1) if m else None
    m = re.search(r"(\d+(?:\.\d+)?(?:\s*[xX]\s*\d+(?:\.\d+)?)?)\s*CM\b", d, re.I)
    return f"{m.group(1).replace(' ', '')} CM" if m else None


def cone_or_roll(uom):
    m = re.match(r"CONE\((\d+(?:\.\d+)?)([KH])\)", uom or "", re.I)
    if m:
        return int(float(m.group(1)) * (1000 if m.group(2).upper() == "K" else 100))
    m = re.match(r"ROLL\((\d+)Y\)", uom or "", re.I)
    return int(m.group(1)) if m else None


def uom_family(u):
    u = str(u or "").upper()
    for k, v in UOM_FAMILY.items():
        if u == k or u.startswith(k + "("):
            return v
    return u.title() if u else None


def shade_from_spec(spec, cat, colour_label):
    rest = spec[len(colour_label):].strip() if colour_label and spec.startswith(colour_label) else spec
    if cat == "thread":
        m = re.search(r"TEX\d+-[A-Z]+\d+-(\w+)-\d+-", rest)
        last = rest.split()[-1] if rest.split() else ""
        if last and not last.endswith("-REG") and re.fullmatch(r"[A-Z0-9]{4,}", last):
            return last
        return m.group(1) if m else None
    if cat == "zipper":
        m = re.search(r"\d+\s*CM\s+(.+)$", rest)
        s = (m.group(1) if m else rest).strip()
        return s.replace("YKK- ", "YKK-") or None
    return None


def item_colour(it):
    m = re.search(r"\((BLACK|WHITE|IVORY|NAVY|GREY|CLEAR|SILVER|GOLD|BROWN|BEIGE)\)|Colou?r:\s*([A-Za-z]+)", it["desc"], re.I)
    return (m.group(1) or m.group(2)).title() if m else None


# ======================================================================== CBD
def read_grid(path):
    if path.lower().endswith(".xls"):
        import xlrd
        sh = xlrd.open_workbook(path).sheet_by_index(0)
        return [[sh.cell_value(r, c) for c in range(sh.ncols)] for r in range(sh.nrows)]
    ws = openpyxl.load_workbook(path, data_only=True).worksheets[0]
    return [[("" if v is None else v) for v in row] for row in ws.iter_rows(values_only=True)]


def style_colour(s):
    s = re.sub(r"^\s*\d+[\s_\-]*", "", str(s))
    s = re.sub(r"[\s_\-]*ONL\s*$", "", s, flags=re.I)
    return s.strip()


def hnorm(v):
    """Header text normalised: lowercase, single spaces (CBD headers often contain line breaks)."""
    return re.sub(r"\s+", " ", str(v)).strip().lower()


def parse_cbd(path):
    g = read_grid(path)
    S = lambda v: str(v).strip()
    out = {"header": {}, "styles": [], "blocks": [], "checks": [], "wash": {}}

    def right_of(label):
        for row in g:
            for c, v in enumerate(row):
                if hnorm(v).rstrip(":").strip() == label.lower():
                    for v2 in row[c + 1:]:
                        if S(v2):
                            return S(v2)
        return ""

    for k in ("File Nos", "Buyer", "Season", "Style Desc."):
        out["header"][k] = right_of(k)

    def headers(*names):
        names = [hnorm(n) for n in names]
        res = []
        for r, row in enumerate(g):
            cells = [hnorm(v) for v in row]
            if all(n in cells for n in names):
                res.append((r, {hnorm(v): c for c, v in enumerate(row) if S(v)}))
        return res

    H = hnorm
    for r, h in headers("Style Nos.", "Qty (pcs)")[:1]:
        osc = h.get(H("OS Cost ID")) or h.get(H("Os Cost Id"))
        for row in g[r + 1:]:
            st = S(row[h[H("Style Nos.")]])
            if not st or S(row[0]).lower() == "total":
                break
            out["styles"].append((st, num(row[h[H("Qty (pcs)")]]), S(row[osc]) if osc is not None else ""))
    all_colours = sorted({style_colour(s) for s, _, _ in out["styles"]})

    anchors = [(r, S(v)) for r, row in enumerate(g) for v in row if S(v).startswith("Style No =")]
    fab_hdrs = headers("Fabrication", "Consumption (Yds/DZn)")
    oth_hdrs = headers("Type", "Other Cost (USD/DZn)")
    if not fab_hdrs:
        out["checks"].append(["Costing blocks found in the CBD", "at least 1", 0, "FAIL"])
    prev = -1
    for bi, (fr, fh) in enumerate(fab_hdrs):
        nxt_fr = fab_hdrs[bi + 1][0] if bi + 1 < len(fab_hdrs) else len(g)
        anc = [a for a in anchors if prev < a[0] < fr]          # only this block's own "Style No =" line
        os_ids = [m.group(0) for row in g[prev + 1:fr] for v in row for m in [re.search(r"\bZ\d{8}-\d+\b", S(v))] if m]
        os_id = os_ids[0] if os_ids else ""
        if anc:
            txt = anc[-1][1].split("=", 1)[1]
            colours = sorted({style_colour(x) for x in txt.split(",") if x.strip()})
        elif os_id and any(o == os_id for _, _, o in out["styles"]):
            colours = sorted({style_colour(s) for s, _, o in out["styles"] if o == os_id})
        elif len(fab_hdrs) == 1:
            colours = all_colours
        else:
            colours = []
            out["checks"].append([f"Block {bi + 1}: which colours it belongs to", "Style No = / OS Cost ID", "not found", "FAIL"])
        prev = fr
        blk = {"colours": colours, "fabrics": [], "others": [], "row": fr + 1, "os_id": os_id}
        tot_fab = tot_oth = None
        col = lambda name, default=None: fh.get(H(name), default)
        for i, row in enumerate(g[fr + 1:nxt_fr], fr + 2):
            if any("total fabric cost" in H(v) for v in row):
                vals = [num(v) for v in row if num(v) is not None]
                tot_fab = vals[-1] if vals else None
                break
            if not S(row[col("Fabrication")]):
                continue
            pc, cc, rc = col("Unit Cost (USD/Yds)"), col("Fabric Cost (USD/DZn)"), col("Fabric Ref Code")
            blk["fabrics"].append({"row": i, "type": S(row[col("Type", 1)]), "supplier": S(row[col("Supplier", 2)]),
                                   "fabrication": S(row[col("Fabrication")]), "cons": num(row[col("Consumption (Yds/DZn)")]),
                                   "price": num(row[pc]) if pc is not None else None,
                                   "cost": num(row[cc]) if cc is not None else None,
                                   "ref": S(row[rc]) if rc is not None else ""})
        oh = [(r, h) for r, h in oth_hdrs if fr < r < nxt_fr]
        if oh:
            r0, h = oh[0]
            rem_col = h.get(H("Remarks"))
            for i, row in enumerate(g[r0 + 1:nxt_fr], r0 + 2):
                if any("total other cost" in H(v) for v in row):
                    vals = [num(v) for v in row if num(v) is not None]
                    tot_oth = vals[-1] if vals else None
                    break
                t = S(row[h[H("Type")]])
                if t:
                    blk["others"].append({"row": i, "type": t.upper(), "cost": num(row[h[H("Other Cost (USD/DZn)")]]),
                                          "remarks": S(row[rem_col]) if rem_col is not None else None})
        fs = sum(f["cost"] or 0 for f in blk["fabrics"])
        os_ = sum(o["cost"] or 0 for o in blk["others"])
        lab = ", ".join(colours) or "colours unknown"
        out["checks"].append([f"Block {bi + 1} ({lab}) fabric rows vs Total Fabric Cost", tot_fab, round(fs, 6),
                              "OK" if tot_fab is not None and abs(fs - tot_fab) < 0.001 else "FAIL"])
        out["checks"].append([f"Block {bi + 1} ({lab}) other rows vs Total Other Cost", tot_oth, round(os_, 6),
                              "OK" if tot_oth is not None and abs(os_ - tot_oth) < 0.001 else "FAIL"])
        for f in blk["fabrics"]:
            if f["cons"] and f["price"] and f["cost"]:
                ok = abs(f["cons"] * f["price"] - f["cost"]) < 0.001
                out["checks"].append([f"Block {bi + 1} fabric row {f['row']} cons x price = cost", f["cost"],
                                      round(f["cons"] * f["price"], 6), "OK" if ok else "FAIL"])
        out["blocks"].append(blk)
    for r, h in headers("Wash Cost (USD/DZn)", "Wash Corporate (USD/DZn)"):
        idc = h.get(H("OS Cost ID")) or h.get(H("Os Cost Id"))
        for row in g[r + 1:r + 12]:
            wc, corp = num(row[h[H("Wash Cost (USD/DZn)")]]), num(row[h[H("Wash Corporate (USD/DZn)")]])
            if wc is None:
                break
            out["wash"][S(row[idc]) if idc is not None else ""] = (wc, corp)
    return out


def cbd_block(cbd, colour):
    """The costing block for a garment colour: best colour-name score, ties or no match = None."""
    if not cbd["blocks"]:
        return None
    if len(cbd["blocks"]) == 1 and (not colour or not cbd["blocks"][0]["colours"]
                                    or any(colour_score(colour, c) for c in cbd["blocks"][0]["colours"])):
        return cbd["blocks"][0]
    sc = sorted(((max([colour_score(colour, c) for c in b["colours"]] or [0]), i) for i, b in enumerate(cbd["blocks"])),
                reverse=True)
    if not sc or sc[0][0] == 0 or (len(sc) > 1 and sc[0][0] == sc[1][0]):
        return None
    return cbd["blocks"][sc[0][1]]


# ======================================================================== BOM
class Bom:
    def __init__(self, path):
        self.wb = openpyxl.load_workbook(path)
        if "New" not in self.wb.sheetnames:
            raise SystemExit("BOM has no 'New' tab")
        self.ws = self.wb["New"]
        self.head = [self.ws.cell(1, c).value for c in range(1, 21)]
        bad = [(COLS[i], EXPECTED_HEAD[i], self.head[i]) for i in range(20)
               if not norm(self.head[i]).startswith(norm(EXPECTED_HEAD[i])[:8])]
        if bad:
            raise SystemExit("The BOM 'New' tab columns are not in the expected order, so the tool would fill the wrong "
                             f"columns. Different columns: {bad}")
        self.rows = [r for r in range(2, self.ws.max_row + 1)
                     if any(not blank(self.ws.cell(r, c).value) for c in range(1, 21))]


COLS = "ABCDEFGHIJKLMNOPQRST"
EXPECTED_HEAD = ["Customer", "Season", "Style", "Style Description", "Garment Color", "Raw Material Type", "Sourcing From",
                 "Vendor", "Vendor Type", "Item", "Item Code", "Item Color", "Composition", "Size", "YY", "Wastage",
                 "Roll length", "UOM", "MOQ", "Unit Price"]
IDX = {c: i for i, c in enumerate(COLS)}


class Row:
    def __init__(self, bom, r, added=False):
        self.orig = r
        self.vals = [bom.ws.cell(r, c).value for c in range(1, 21)] if isinstance(r, int) else [None] * 20
        self.st, self.src, self.notes, self.po_desc, self.added = {}, [], [], "", added
        self.colour = None
        self.colour_label = None
        self.same_cat_rows, self.is_shell = 1, False

    def get(self, col):
        return self.vals[IDX[col]]

    def fill(self, col, value, source, note, kind="FILL"):
        i = IDX[col]
        old = self.vals[i]
        if not blank(old):
            return False
        self.vals[i] = value
        self.st[i] = (kind, note, None, source)
        return True

    def soft(self, col, value, source, note):
        return self.fill(col, value, source, note, kind="SOFT")

    def update(self, col, value, source, note):
        i = IDX[col]
        old = self.vals[i]
        if str(old).strip() == str(value).strip():
            return
        if blank(old):
            self.fill(col, value, source, note)
            return
        self.vals[i] = value
        self.st[i] = ("UPDATE", note, old, source)

    def flag(self, col, source, note, src_value=None, update=False):
        i = IDX[col]
        if update and src_value is not None:
            self.update(col, src_value, source, note + " (overwritten, --update mode)")
            return
        extra = f" | Source value: {src_value}" if src_value is not None else ""
        if i in self.st and self.st[i][0] in ("FILL", "SOFT"):
            k, n0, o0, s0 = self.st[i]
            self.st[i] = ("FILLCHECK", f"{n0}. CHECK: {note}", None, f"{s0}; {source}")
        elif i in self.st and self.st[i][0] in ("CHECK", "FILLCHECK", "UPDATE"):
            k, n0, o0, s0 = self.st[i]          # keep every earlier flag on this cell
            if note not in n0:
                self.st[i] = ("CHECK" if k == "UPDATE" else k, f"{n0} || ALSO: {note}{extra}", o0, f"{s0}; {source}")
        else:
            self.st[i] = ("CHECK", note + extra, self.vals[i], source)


# ======================================================================== matching
def bom_category(row):
    m, j = first_line(row.get("M")), str(row.get("J") or "")
    c = categorize(m) or categorize(j)
    if str(row.get("F") or "").strip().lower() == "fabric" and c not in ("fusing", "pocketing"):
        c = "fabric"
    return c


def lines_for(item, garment):
    """Lines of a PO item for one garment colour. Items not split by garment colour (e.g. fabric 'WHITE',
    poly bags, size strips) return all their lines. A split item gives NOTHING for an unknown garment colour
    (never falls back to every colour's lines)."""
    if not item.get("_split"):
        return item["lines"]
    if not garment:
        return []
    return [l for l in item["lines"] if l.get("owner") == garment]


def colour_split(item, garment_labels):
    return any(spec_colour(l["spec"]) in garment_labels for l in item["lines"])


def norm_desc(d):
    return norm(re.sub(r"\(PO-\d+\)", "", d))


def is_code(t):
    return (len(t) >= 4 and re.search(r"[A-Z]", t) and re.search(r"\d", t)
            and not re.fullmatch(r"\d+(?:\.\d+)?(?:X\d+(?:\.\d+)?)*(?:CM|MM|M|L|YDS?|PCS)?", t)
            and not re.search(r"\d+(?:CM|MM)$", t) and not re.fullmatch(r"CW-?\d+", t)
            and not re.fullmatch(r"PP\d+|PE\d*|LDPE.*|\d{1,3}(?:D|OZ|G|S)|\d+GSM|UV\d+|ISO-?\d+", t))


def bom_codes(row):
    txt = f"{first_line(row.get('K'))} {first_line(row.get('M'))}"
    return {t for t in re.findall(r"\b[A-Z0-9]+(?:-[A-Z0-9]+)*\b", txt.upper()) if is_code(t)}


def narrow(row, cands, cat):
    why = []
    m1 = first_line(row.get("M"))
    codes = bom_codes(row)
    # hyphenated codes without digits (e.g. "Size strip- UNIQUE DUN-MSS") also pick out the exact PO item,
    # so a look-alike item ("DUN-MSS2") is not mixed into the row
    txt = f"{first_line(row.get('K'))} {m1}".upper()
    codes |= {t for t in re.findall(r"(?<![A-Z0-9-])[A-Z]{2,}(?:-[A-Z0-9]{2,})+(?![A-Z0-9-])", txt) if len(t) >= 6}
    if codes:
        hit = [c for c in cands if any(re.search(rf"(?<![A-Z0-9]){re.escape(k)}(?![A-Z0-9])", c["desc"].upper()) for k in codes)]
        if hit and len(hit) < len(cands) or (hit and len(cands) == 1):
            cands = hit
            why.append("code")
    # Contradiction filters: if the BOM states a type no. / size / tex, drop every PO item that states a DIFFERENT
    # value, even when it is the only candidate. If nothing is left, the row is reported, never filled from a wrong item.
    if cat in TYPE_NUMBER_CATS:
        k = row.get("K")
        bn = int(k) if isinstance(k, (int, float)) else type_number(m1)
        if bn is not None:
            keep = [c for c in cands if type_number(c["desc"]) in (None, bn)]
            if not keep:
                return [], f"BOM says type {bn}, the PO only has type {sorted({type_number(c['desc']) for c in cands})}"
            if len(keep) < len(cands):
                why.append("type no.")
            cands = keep
    bsz = size_tokens(f"{row.get('N') or ''} {m1}")
    if bsz:
        kinds = {k for k, _ in bsz}

        def size_ok(c):
            cs = {t for t in size_tokens(c["desc"]) if t[0] in kinds}
            return not cs or bool(cs & bsz)
        keep = [c for c in cands if size_ok(c)]
        if not keep:
            return [], f"BOM size {sorted(v for _, v in bsz)} not found; PO has {sorted({v for c in cands for _, v in size_tokens(c['desc'])})}"
        if len(keep) < len(cands):
            why.append("size")
        cands = keep
    tex = re.search(r"tex\s*(\d+)", f"{row.get('K') or ''} {row.get('Q') or ''} {m1}", re.I)
    if tex:
        def tex_ok(c):
            ct = re.findall(r"\btex[- ]?(\d+)", c["desc"], re.I)
            return not ct or tex.group(1) in ct
        keep = [c for c in cands if tex_ok(c)]
        if not keep:
            return [], f"BOM says Tex {tex.group(1)}, not on the PO"
        if len(keep) < len(cands):
            why.append("tex")
        cands = keep
    if len(cands) > 1:
        words = set(re.findall(r"[A-Z]{4,}", f"{row.get('Q') or ''} {m1}".upper())) - {"THREAD", "PERMA", "SPUN", "PLACEMENT", "BODY", "LABEL"}
        hit = [c for c in cands if words & set(re.findall(r"[A-Z]{4,}", c["desc"].upper()))]
        if hit and len(hit) < len(cands):
            cands = hit
            why.append("keyword")
    if len(cands) > 1 and row.colour_label and "DTM" in f"{row.get('L') or ''} {m1}".upper():
        with_col = [c for c in cands if c["_split"] and lines_for(c, row.colour_label)]
        if with_col and len(with_col) < len(cands):
            cands = with_col
            why.append("colour split")
    return cands, "+".join(why) or "item type"


def distinct_fields(cands, colour_label):
    sig = set()
    for c in cands:
        ls = lines_for(c, colour_label) or c["lines"]
        sig.add((tuple(sorted({l["price"] for l in ls})), po_size(c, ls), po_code(c), uom_family(ls[0]["uom"]) if ls else None,
                 cone_or_roll(ls[0]["uom"]) if ls else None))
    return len(sig) > 1


# ======================================================================== fill
def apply_po(row, items, colour_label, length, cat, update, all_items):
    """Fill one BOM row from one PO item, or several identical ones (same desc/price)."""
    lines = []
    for it in items:
        lines += lines_for(it, colour_label)          # never all colours' lines for a split item
    if length:
        lines = [l for l in lines if re.search(rf"\b{re.escape(length)}\b", l["spec"])]
    n_ = row.get("N")
    len_problem = None
    mlen = re.search(r"(\d+(?:\.\d+)?)\s*CM\b", str(n_ or ""), re.I)
    if not length and mlen and any(re.search(r"\b\d+\s*CM\b", l["spec"]) for l in lines):
        hit = [l for l in lines if re.search(rf"\b{re.escape(mlen.group(1))}\s*CM\b", l["spec"])]
        if hit:
            lines = hit
        else:
            have = sorted({m.group(0) for l in lines for m in [LEN_RE.search(l["spec"])] if m})
            len_problem = f"BOM length {mlen.group(0)} not on the PO lines ({have})"
    if not length and not blank(n_) and re.fullmatch(r"\d{1,2}", str(n_).strip().split(".")[0]):
        sz = str(n_).strip().split(".")[0]
        hit = [l for l in lines if re.search(rf"\bSIZE\s*{sz}\b", l["spec"], re.I)]
        if hit:
            lines = hit
    if not lines:
        row.notes.append(f"PO item found but it has no line for colour {colour_label}")
        return
    it = items[0]
    po = it["po"]
    src = (f"PO {po['po_no']} (PDF p{lines[0]['page']}) item {it['item_no']}" if len(items) == 1 else
           "PO " + ", ".join(sorted({f"{x['po']['po_no']} item {x['item_no']} p{x['lines'][0]['page'] if x['lines'] else x['po']['page']}" for x in items})))
    if len_problem:
        row.flag("N", src, len_problem + ". Nothing filled from this PO for the row")
        row.notes.append(len_problem)
        return
    row.src.append(src)
    row.po_desc = f"{it['desc'][:110]} | {sum(l['qty'] for l in lines):,.0f} {lines[0]['uom']}" + (f" ({colour_label})" if colour_label and it["_split"] else "")
    supplier = po["supplier"]
    # vendor
    if not row.fill("H", supplier, src, "PO supplier"):
        if norm_vendor(row.get("H")) != norm_vendor(supplier):
            row.flag("H", src, f"BOM vendor differs from PO vendor '{supplier}'", supplier, update)
    m_up = str(row.get("M") or "").upper()
    for w in VENDOR_WORDS:
        if re.search(rf"(?<![A-Z]){re.escape(w)}(?![A-Z])", m_up) and w not in supplier.upper():
            row.flag("H", src, f"BOM description mentions '{w.title()}' but the PO vendor is {supplier}")
            break
    # price
    cnt = Counter(l["price"] for l in lines)
    price = cnt.most_common(1)[0][0]
    pnote = "PO unit price"
    if len(cnt) > 1:
        others = ", ".join(f"{p} on {c} line(s)" for p, c in cnt.items() if p != price)
        pnote += f" (most lines; exceptions: {others})"
    if not row.fill("T", price, src, pnote):
        t_ = num(row.get("T"))
        if t_ is None or abs(t_ - price) > 1e-5:
            row.flag("T", src, f"PO unit price is {price}", price, update)
    if len(cnt) > 1:
        row.flag("T", src, f"The PO has more than one price for this item ({', '.join(f'{p} x{c} lines' for p, c in cnt.items())}). Check which applies")
    if po["currency"] and po["currency"] != "USD":
        row.flag("T", src, f"PO currency is {po['currency']}, not USD. Confirm the price currency")
        row.notes.append(f"PO currency is {po['currency']}")
    # code
    code = po_code(it)
    if isinstance(code, str) and code.startswith("T-"):
        tx = re.search(r"TEX(\d+)-", " ".join(l["spec"] for l in lines))
        if tx:
            code = f"{code} (Tex {tx.group(1)})"
    if code is not None:
        bk = first_line(row.get("K"))
        if not row.fill("K", code, src, "Code from PO description"):
            same_num = num(bk) is not None and num(code) is not None and num(bk) == num(code)
            in_desc = len(norm(bk)) >= 3 and re.search(rf"(?<![a-z0-9]){re.escape(norm(bk))}(?![a-z0-9])", norm_words(it["desc"]))
            if norm(bk) != norm(code) and not in_desc and not same_num:
                row.flag("K", src, f"PO item is '{it['desc'][:70]}' (code {code})", code, update)
    # size
    sz = f"{length}" if length else po_size(it, lines)
    if sz:
        bn = row.get("N")
        if not row.fill("N", sz, src, "Size from PO"):
            if "cm" in str(bn).lower() and size_tokens(bn) and size_tokens(sz) and not (size_tokens(bn) & size_tokens(sz)):
                row.flag("N", src, f"PO size is {sz}", sz, update)
    # colour / shade
    bl = str(row.get("L") or "").strip()
    shade = None
    if it["_split"] and colour_label:
        shade = shade_from_spec(lines[0]["spec"], cat, spec_colour(lines[0]["spec"]))
        if cat == "fabric":
            shade = spec_colour(lines[0]["spec"])
    elif not it["_split"]:
        lab = spec_colour(lines[0]["spec"]) if lines[0]["spec"] else None
        shade = lab if (cat == "fabric" and lab) else item_colour(it)
    if shade:
        if blank(bl):
            row.fill("L", shade, src, "Colour/shade from PO")
        elif bl.upper() == "DTM":
            row.update("L", shade, src, f"PO shade for this colour (BOM said DTM). PO spec: {lines[0]['spec']}")
        elif "REPEAT" in bl.upper() or "AS PER" in bl.upper():
            row.update("L", f"{shade} ({bl})", src, "PO colour added, buyer instruction kept")
        else:
            po_word = spec_colour(lines[0]["spec"]) if it["_split"] else shade
            po_word = po_word or shade
            if not colour_match(bl, po_word) and letters(bl) not in letters(lines[0]["spec"]) and bl.upper() not in ("ALL", "N/A", "NA"):
                row.flag("L", src, f"PO colour/shade is {po_word} {shade if shade != po_word else ''}".strip(), shade, update)
    # cone / roll length
    cl = cone_or_roll(lines[0]["uom"])
    if cl:
        q = row.get("Q")
        if not row.fill("Q", cl, src, f"Length from PO UOM {lines[0]['uom']} ({'m per cone' if 'CONE' in lines[0]['uom'].upper() else 'yds per roll'})"):
            if num(q) != cl:
                row.flag("Q", src, f"PO {'cone' if 'CONE' in lines[0]['uom'].upper() else 'roll'} length is {cl}. PO item: {it['desc'][:60]}", cl, update)
    # UOM family must match the price unit
    fam = uom_family(lines[0]["uom"])
    if fam and not blank(row.get("R")) and str(row.get("R")).strip().lower() != fam.lower():
        row.update("R", fam, src, f"PO price is per {lines[0]['uom']}")
    elif fam:
        row.fill("R", fam, src, "PO UOM")
    # sourcing
    if po["type"] == "Local PO" and str(row.get("G") or "").strip().upper() != "BD":
        row.update("G", "BD", src, f"Booked as a Local PO in Bangladesh (BOM said {row.get('G')})")
    # placeholder item name
    if str(row.get("J") or "").strip().upper() == "DTM":
        row.update("J", LABEL.get(cat, cat), "BOM description", "Item said 'DTM'")


def apply_cbd(row, cbd, cat, has_po, update):
    col = row.colour
    blk = cbd_block(cbd, col) if col else (cbd["blocks"][0] if len(cbd["blocks"]) == 1 else None)
    ftag = lambda f: f"CBD {cbd['header'].get('File Nos', '')} block ({', '.join(blk['colours'])}) row {f['row']}"
    if cbd["header"].get("Season"):
        row.fill("B", cbd["header"]["Season"], "CBD header", "Season from CBD")
    if blk is None:
        if cat in ("fabric", "pocketing", "washing", "fusing"):
            row.notes.append(f"No CBD costing block found for garment colour '{col}', so no CBD values")
        return
    m_all = str(row.get("M") or "")
    if cat == "fabric":
        code = (first_line(row.get("K")) or first_line(row.get("J")) or first_line(row.get("M"))).strip().rstrip(",")
        code = re.split(r"[\s,]", code.lstrip("#"))[0].lower()
        fab = [f for f in blk["fabrics"] if code and (norm(code) in norm(f["ref"]) or norm(code) in norm(f["fabrication"]))]
        own_code = re.search(r"[A-Z0-9]+(?:-[A-Z0-9]+){2,}|\b(?=[A-Z0-9]*\d)(?=[A-Z0-9]*[A-Z])[A-Z0-9]{6,}\b",
                             f"{row.get('K') or ''} {row.get('J') or ''} {first_line(row.get('M'))}".upper())
        if len(fab) != 1:
            if row.is_shell and not own_code:   # only a shell row WITHOUT its own fabric code may use the CBD SHELL line
                fab = [f for f in blk["fabrics"] if f["type"].upper() == "SHELL"] if len(blk["fabrics"]) > 1 else blk["fabrics"]
            else:
                row.notes.append(f"Fabric code '{code}' not found in the CBD, so no CBD values")
                fab = []
        if len(fab) == 1:
            f = fab[0]
            yy = round(f["cons"] / 12, 4) if f["cons"] else None
            if yy:
                if not row.fill("O", yy, ftag(f), f"CBD consumption {f['cons']} yds/dz / 12") and not close(row.get("O"), yy):
                    row.flag("O", ftag(f), f"CBD consumption {f['cons']} yds/dz = {yy} yds/pc", yy, update)
            if not has_po:
                if f["supplier"]:
                    row.soft("H", f["supplier"], ftag(f), "Supplier from CBD (no PO in the PDF)")
                if f["price"]:
                    row.soft("T", f["price"], ftag(f), "CBD costing price, NOT a PO price (no PO in the PDF)")
            elif f["price"] and not blank(row.get("T")) and not close(row.get("T"), f["price"]):
                row.notes.append(f"CBD fabric price {f['price']} differs from the BOM/PO price {row.get('T')}")
    elif cat == "pocketing":
        pk = [f for f in blk["fabrics"] if "pocket" in (f["ref"] + f["fabrication"]).lower()] or \
             [f for f in blk["fabrics"] if f["type"].upper() != "SHELL"]
        if len(pk) > 1 and row.get("L"):
            pk = [f for f in pk if letters(row.get("L")) and letters(row.get("L")) in letters(f["fabrication"] + f["ref"])] or pk
        if len(pk) == 1:
            f = pk[0]
            if f["cons"]:
                row.fill("O", round(f["cons"] / 12, 4), ftag(f), f"CBD consumption {f['cons']} yds/dz / 12")
            if not has_po:
                row.soft("H", f["supplier"], ftag(f), "Supplier from CBD (no pocketing PO in the PDF)")
                if f["ref"]:
                    row.soft("K", f["ref"], ftag(f), "CBD Fabric Ref Code")
                if f["price"]:
                    row.soft("T", f["price"], ftag(f), "CBD costing price, NOT a PO price (no pocketing PO in the PDF)")
            wb_ = re.search(r'(\d{2,3})\s*[\"”]\s*CW|CW\s*-?\s*(\d{2,3})\s*[\"”]', m_all, re.I)
            wc = re.search(r'(\d{2}(?:/\d)?)\s*[\"”]', f["fabrication"])
            if wb_ and wc and (wb_.group(1) or wb_.group(2)) != wc.group(1):
                row.flag("N", ftag(f), f"Width not filled: BOM says {wb_.group(1) or wb_.group(2)}\" CW but CBD fabrication says {wc.group(1)}\"")
            row.notes.append("Pocketing values from CBD")
    elif cat in ("washing", "fusing"):
        key = "WASH" if cat == "washing" else "INTERLINING"
        oth = [o for o in blk["others"] if key in o["type"]]
        if len(oth) == 1 and oth[0]["cost"]:
            o = oth[0]
            if cat == "fusing":
                if o["remarks"] is None:
                    row.notes.append(f"CBD interlining line has no Remarks column, so it may include other items: not filled")
                    return
                if re.search(r"elastic|\band\b|&|\+", o["remarks"], re.I):
                    row.notes.append(f"CBD has '{o['remarks']}' combined ({o['cost']}/dz), so no interlining price can be split out")
                    return
            if row.same_cat_rows > 1:
                row.notes.append(f"CBD {o['type']} {o['cost']}/dz is one lump sum for {row.same_cat_rows} BOM rows of this type: not filled")
                return
            pc = round(o["cost"] / 12, 5)
            src = f"CBD {cbd['header'].get('File Nos', '')} block ({', '.join(blk['colours'])}) row {o['row']} {o['type']} {o['cost']}/dz"
            note = f"CBD cost per dozen / 12, NOT a PO price"
            if cat == "washing" and blk.get("os_id") in cbd["wash"]:
                wc, corp = cbd["wash"][blk["os_id"]]
                if corp:
                    note += f". CBD wash = {wc} wash + {corp} corporate per dz; pure wash cost = {round(wc / 12, 5)}/pc"
            if not row.soft("T", pc, src, note):
                if not close(row.get("T"), pc, 0.02):
                    row.flag("T", src, f"CBD cost per piece is {pc}", pc, update)


# ======================================================================== main engine
def build(bom_path, cbd_path, pdf_path, update=False):
    bad = [(d, e, categorize(d)) for d, e in CATEGORY_TESTS.items() if categorize(d) != e]
    if bad:
        raise SystemExit(f"CATEGORIES self-test failed (a pattern edit broke these): {bad}")
    pos, items, warnings = parse_po(pdf_path)
    cbd = parse_cbd(cbd_path)
    bom = Bom(bom_path)
    # POs that belong to another file are not used for matching
    cfile = cbd["header"].get("File Nos", "")
    if cfile:
        other = [po for po in pos if po["file_no"] and po["file_no"] != cfile]
        for po in other:
            warnings.append(f"PO {po['po_no']} is for file {po['file_no']}, not {cfile}: NOT used")
        if other:
            keep = {id(po) for po in pos if po not in other}
            items = [it for it in items if id(it["po"]) in keep]
            pos = [po for po in pos if id(po) in keep]
    po_rows, po_ok = po_checks(pos)
    failed_pos = {r_[0] for r_ in po_rows if r_[-1] == "FAIL"}

    garment = [str(bom.ws.cell(r, 5).value).strip() for r in bom.rows if not blank(bom.ws.cell(r, 5).value)]
    garment = list(dict.fromkeys(garment))
    # every PO colour label belongs to at most ONE garment colour (exact name first, ties = ambiguous)
    labels = Counter(spec_colour(l["spec"]) for it in items for l in it["lines"] if spec_colour(l["spec"]))
    owner = {lab: best_owner(lab, garment) for lab in labels}
    for lab in labels:
        if owner[lab] is None and any(colour_score(g, lab) for g in garment):
            warnings.append(f"PO colour '{lab}' fits more than one garment colour equally ({', '.join(g for g in garment if colour_score(g, lab))}): its lines are NOT used")
    for it in items:
        for l in it["lines"]:
            l["owner"] = owner.get(spec_colour(l["spec"]))
        it["_split"] = any(l["owner"] for l in it["lines"])
        odd = sorted({spec_colour(l["spec"]) for l in it["lines"] if spec_colour(l["spec"]) and not l["owner"]})
        if it["_split"] and odd:
            warnings.append(f"PO {it['po']['po_no']} item {it['item_no']}: colour label(s) {odd} match no garment colour: those lines are NOT used")
    any_split = any(it["_split"] for it in items)
    gmap = {g: sorted(lab for lab, o in owner.items() if o == g) for g in garment}
    for g, labs in gmap.items():
        if not labs and any_split:
            warnings.append(f"Garment colour '{g}' was not found in the PO colour labels: colour-split PO items are NOT used for its rows")

    rows = []
    for r in bom.rows:
        row = Row(bom, r)
        e = row.get("E")
        if blank(e) and len(garment) == 1:
            row.fill("E", garment[0], "only garment colour in this BOM/CBD", "Garment colour (single-colour order)")
        row.colour = str(row.get("E") or "").strip() or None
        row.colour_label = row.colour if row.colour and gmap.get(row.colour) else None
        if any_split and not row.colour_label:
            row.flag("E", "PO colour labels", "Garment colour blank or not found in the PO colour labels: colour-split PO items not used for this row")
        row.cat = bom_category(row)
        rows.append(row)
    fab_rows = Counter((r_.colour, r_.cat) for r_ in rows)
    seen = {}
    for row in rows:                       # exact duplicate BOM rows
        key = (row.colour,) + tuple(norm(v) for v in row.vals)
        if key in seen:
            row.flag("J", "BOM", f"This row looks like a duplicate of BOM row {seen[key]}")
        else:
            seen[key] = row.orig
    for row in rows:
        row.same_cat_rows = fab_rows[(row.colour, row.cat)]
        row.is_shell = row.cat == "fabric" and (re.search(r"shell|self", f"{row.get('J') or ''} {first_line(row.get('M'))}", re.I)
                                                 is not None or fab_rows[(row.colour, "fabric")] == 1)

    # ---- candidates
    by_cat = defaultdict(list)
    for it in items:
        if it["cat"]:
            by_cat[it["cat"]].append(it)
    for row in rows:
        cat = row.cat
        if cat == "fabric":
            toks = {t.lstrip("#") for t in re.findall(r"#?[A-Z0-9]+(?:-[A-Z0-9]+){2,}",
                                                     f"{row.get('K') or ''} {row.get('J') or ''} {row.get('M') or ''}".upper())}
            toks |= {t for t in re.findall(r"#?([A-Z0-9]{6,})\b", f"{row.get('K') or ''}".upper()) if re.search(r"\d", t)}
            cands = [it for it in items if it["cat"] == "fabric" and any(norm(t) in norm(it["desc"]) for t in toks)]
            why = "fabric code"
        else:
            cands = by_cat.get(cat, []) if cat else []
            cands, why = narrow(row, cands, cat) if cands else ([], "")
        cands = [c for c in cands if lines_for(c, row.colour_label)]
        row.cands, row.why = cands, why

    # ---- resolve: combine identical items, split, pair, remove taken
    def groups_of(cands):
        g = defaultdict(list)
        for c in cands:
            g[norm_desc(c["desc"])].append(c)
        return list(g.values())

    taken = set()                      # (item key, garment colour)
    for row in rows:
        gs = groups_of(row.cands)
        row.groups = gs
        if len(gs) == 1:
            taken |= {(c["key"], row.colour) for c in gs[0]}
    is_taken = lambda g, colour: any((c["key"], colour) in taken for c in g)
    final = []
    pair_groups = defaultdict(list)
    for row in rows:
        gs = row.groups
        row.plan = None
        if not row.cat:
            row.plan = ("none", "item type not recognised")
        elif not gs:
            row.plan = ("none", f"no PO for '{LABEL.get(row.cat, row.cat)}' in the PDF" if not by_cat.get(row.cat) or row.cat == "fabric"
                        else (row.why if row.why and not row.why.startswith(("code", "item", "size+", "type")) and " " in row.why
                              else f"no matching PO line for this colour/size ({row.why})"))
        elif len(gs) == 1:
            row.plan = ("one", gs[0])
        else:
            pair_groups[(row.cat, row.colour)].append(row)
    for key, grp in pair_groups.items():
        same_group_rows = [r for r in rows if (r.cat, r.colour) == key]
        for row in grp:
            gs = [g for g in row.groups if not is_taken(g, row.colour) or len(same_group_rows) == 1]
            if len(same_group_rows) == 1:
                if row.cat in ALWAYS_SPLIT_CATS or distinct_fields([g[0] for g in gs], row.colour_label):
                    row.plan = ("split", gs)
                else:
                    row.plan = ("agree", [c for g in gs for c in g])
            elif not gs:
                row.plan = ("none", "the matching PO items are already used by other BOM rows")
            elif len(gs) == 1:
                row.plan = ("one", gs[0])
                row.elim = True
        amb = [r for r in grp if r.plan is None]
        if amb:
            gs = [g for g in amb[0].groups if not is_taken(g, amb[0].colour)]
            ident = lambda r: tuple(norm(r.get(c)) for c in "JKLMNQ")
            if len(amb) == len(gs) and all(r.groups == amb[0].groups and ident(r) == ident(amb[0]) for r in amb):
                for r, g in zip(amb, gs):
                    r.plan = ("one", g)
                    r.paired = True
            elif not distinct_fields([g[0] for g in gs] or [g[0] for g in amb[0].groups], amb[0].colour_label):
                for r in amb:
                    r.plan = ("agree", [c for g in r.groups for c in g])
            else:
                for r in amb:
                    r.plan = ("none", f"{len(r.groups)} different PO items fit and they cannot be told apart: " +
                              "; ".join(g[0]["desc"][:40] for g in r.groups))

    usage = defaultdict(set)
    for row in rows:
        if row.plan[0] in ("one", "agree"):
            for c in row.plan[1]:
                usage[(c["key"], row.colour)].add(first_line(row.get("M")).lower())
    for row in rows:
        if row.plan[0] in ("one", "agree") and any(len(usage[(c["key"], row.colour)]) > 1 for c in row.plan[1]):
            row.shared = True

    used = set()
    for row in rows:
        kind, payload = row.plan
        cat = row.cat
        if kind == "none":
            out = [row]
            cbd_cat = cat in ("fabric", "pocketing", "washing", "fusing")
            apply_cbd(row, cbd, cat, False, update)
            if not cbd_cat or cat == "fusing":
                if not any(n.startswith("CBD has") for n in row.notes):
                    row.notes.append(f"NO PO: {payload}")
                    if cat not in ("washing",):
                        i = IDX["J"]
                        row.st.setdefault(i, ("NOMATCH", f"No PO found: {payload}", row.get("J"), ""))
        elif kind in ("one", "agree"):
            its = payload
            used |= {c["key"] for c in its}
            # one PO item with several lengths for this colour (e.g. zipper 17 CM / 18 CM) -> split by length
            ls = [l for c in its for l in lines_for(c, row.colour_label)]
            lengths = sorted({m.group(0) for l in ls for m in [re.search(r"\b\d+\s*CM\b", l["spec"])] if m},
                             key=lambda x: num(x.split()[0]))
            if len(lengths) > 1 and blank(row.get("N")) and len(its) == 1 and cat in LENGTH_SPLIT_CATS:
                out = []
                for k, ln in enumerate(lengths):
                    nr = clone(row, bom, added=k > 0)
                    apply_po(nr, its, row.colour_label, ln, cat, update, items)
                    apply_cbd(nr, cbd, cat, True, update)
                    rng = waist_range(items, row.colour_label, its[0], ln, lengths)
                    nstat = nr.st.get(IDX["N"])
                    if rng and nstat:
                        nr.vals[IDX["N"]] = f"{ln} ({rng})"
                        nr.st[IDX["N"]] = ("SOFT", nstat[1] + f". Waist range {rng} INFERRED from PO quantities (not printed on PO)", None, nstat[3])
                    nr.flag("O", nr.src[0] if nr.src else "PO", f"One per garment: this {ln} row applies only to "
                            f"{'waist ' + rng if rng else 'some sizes'}. Do not add the length rows together")
                    if k > 0:
                        nr.notes.append(f"ADDED ROW: split of BOM row {row.orig} by length")
                    out.append(nr)
                out[0].notes.append(f"BOM row {row.orig} split by length ({', '.join(lengths)})")
            else:
                apply_po(row, its, row.colour_label, None, cat, update, items)
                apply_cbd(row, cbd, cat, True, update)
                if kind == "agree" and len(its) > 1:
                    row.notes.append(f"{len(its)} PO items match with the same values; all used")
                if getattr(row, "paired", False):
                    row.flag("J", row.src[0] if row.src else "PO", "Rows look identical; paired to PO items by row order. Confirm")
                if getattr(row, "elim", False):
                    row.flag("J", row.src[0] if row.src else "PO", "Matched only by elimination (the other PO items were used by other rows). Confirm")
                if getattr(row, "shared", False):
                    row.flag("J", row.src[0] if row.src else "PO", "The same PO item also fills another BOM row with a different description. Confirm which row it belongs to")
                out = [row]
        elif kind == "split":
            out = []
            gs = payload
            for k, g in enumerate(gs):
                used |= {c["key"] for c in g}
                nr = clone(row, bom, added=k > 0)
                apply_po(nr, g, row.colour_label, None, cat, update, items)
                apply_cbd(nr, cbd, cat, True, update)
                if not po_size(g[0]) or cat in ALWAYS_SPLIT_CATS:
                    ml = str(row.get("M") or "").split("\n")
                    ml[0] = f"{ml[0]} - {g[0]['desc']}"
                    nr.update("M", "\n".join(ml), nr.src[0] if nr.src else "PO", "Description from PO (BOM row split by PO item)")
                if k > 0:
                    nr.notes.append(f"ADDED ROW: split of BOM row {row.orig} ({k + 1} of {len(gs)})")
                if cat not in ALWAYS_SPLIT_CATS:
                    msg = (f"BOM row {row.orig} matched {len(gs)} different PO items, so it was split into {len(gs)} rows. "
                           "Check that each item really belongs to this garment (for example a different size or fit)")
                    nr.flag("J", nr.src[0] if nr.src else "PO", msg)
                    nr.flag("T", nr.src[0] if nr.src else "PO", msg)
                out.append(nr)
            out[0].notes.append(f"BOM row {row.orig} split into {len(gs)} rows, one per PO item")
        for o in out:
            # code written in the BOM's own description (e.g. "Care Label - 8181D- Unique") when nothing else gave one
            if blank(o.get("K")) and isinstance(o.orig, int):
                m1u = first_line(row.get("M")).upper()
                own = [t for t in re.findall(r"(?:^|\s)-\s*([A-Z0-9]+(?:-[A-Z0-9]+)*)\b", m1u) if is_code(t)]
                # only when the text names ONE code: "HANGER -DB-MD4843B (..) & DB-MD4847B (..)" names two, so copy nothing
                all_codes = {t for t in re.findall(r"\b[A-Z0-9]+(?:-[A-Z0-9]+)*\b", m1u) if is_code(t)}
                if len(own) == 1 and len(all_codes) == 1:
                    o.soft("K", own[0], "BOM description (col M)", "Code copied from the BOM's own item text (the PO does not show one)")
            if str(o.get("F") or "").strip().lower() == "fabric" and blank(o.get("N")) and IDX["N"] not in o.st:
                w = re.search(r'(\d{2,3})\s*[\"”]\s*CW|CW\s*-?\s*(\d{2,3})\s*[\"”]', str(o.get("M") or ""), re.I)
                if w:
                    o.fill("N", f'{w.group(1) or w.group(2)}"CW', "BOM description (col M)", "Width written in the BOM item text")
        for o in out:
            if any(re.search(rf"\bPO {re.escape(fp)}\b", " ".join(o.src)) for fp in failed_pos):
                o.flag("T", "Checks sheet", "This PO FAILED its totals self-check, so values read from it may be wrong")
                o.flag("H", "Checks sheet", "This PO FAILED its totals self-check")
        final.extend(out)

    # PO items not used: note on same-category rows, then extra rows
    unused = [it for it in items if it["key"] not in used]
    for it in unused:
        for row in final:
            if row.cat == it["cat"] and row.src:
                row.flag("M", f"PO {it['po']['po_no']} item {it['item_no']}",
                         f"Another {LABEL.get(it['cat'], it['cat'])} PO exists and was not used: {it['desc'][:70]}")
    extra = []
    for it in unused:
        cols = [gc for gc in garment if it["_split"] and lines_for(it, gc)] or ["ALL"]
        for gc in cols:
            er = Row(bom, None, added=True)
            er.orig = "PO only"
            for c in "ACD":
                er.vals[IDX[c]] = bom.ws.cell(bom.rows[0], IDX[c] + 1).value
            er.vals[IDX["E"]] = gc
            er.vals[IDX["F"]] = RAW_TYPE.get(it["cat"], "Packaging Trims")
            er.vals[IDX["J"]] = LABEL.get(it["cat"], "PO item") + (" (NI)" if re.search(r"\bNI\b", it["desc"]) else "")
            er.colour, er.colour_label, er.cat = gc, (gc if gc != "ALL" else None), it["cat"]
            er.fill("M", it["desc"], f"PO {it['po']['po_no']} item {it['item_no']}", "PO description")
            apply_po(er, [it], er.colour_label, None, it["cat"], False, items)
            if cbd["header"].get("Season"):
                er.fill("B", cbd["header"]["Season"], "CBD header", "Season from CBD")
            er.flag("J", er.src[0] if er.src else "PO", "PO item that is NOT in the buyer BOM. Add only if confirmed for this style")
            er.notes.append("NEW ROW: PO item not in buyer BOM")
            extra.append(er)
    return {"bom": bom, "rows": final + extra, "pos": pos, "items": items, "cbd": cbd, "po_rows": po_rows, "po_ok": po_ok,
            "gmap": gmap, "used": used, "unused": unused, "warnings": warnings, "failed_pos": failed_pos}


def clone(row, bom, added):
    nr = Row(bom, row.orig, added=added)
    nr.vals = list(row.vals)
    nr.st = dict(row.st)
    nr.colour, nr.colour_label, nr.cat = row.colour, row.colour_label, row.cat
    nr.same_cat_rows, nr.is_shell = getattr(row, "same_cat_rows", 1), getattr(row, "is_shell", False)
    return nr


def waist_range(items, colour_label, zip_item, length, lengths):
    """Zipper lengths usually follow waist size. Infer the waist range from a size-wise PO (e.g. care label 30X29)."""
    zl = {ln: sum(l["qty"] for l in lines_for(zip_item, colour_label) if re.search(rf"\b{re.escape(ln)}\b", l["spec"])) for ln in lengths}
    best = None
    for it in items:
        ls = lines_for(it, colour_label) if it["_split"] else []
        w = defaultdict(float)
        for l in ls:
            m = re.search(r"\b(\d{2})\s*X\s*\d{2}\b", l["spec"])
            if m:
                w[int(m.group(1))] += l["qty"]
        if len(w) < 3:
            continue
        waists = sorted(w)
        # contiguous partition of waists into len(lengths) groups whose qty share matches the zipper share
        tot_z, tot_w = sum(zl.values()), sum(w.values())
        if len(lengths) != 2 or not tot_z:
            return None
        share = zl[lengths[0]] / tot_z
        cut = min(range(1, len(waists)), key=lambda k: abs(sum(w[x] for x in waists[:k]) / tot_w - share))
        got = sum(w[x] for x in waists[:cut]) / tot_w
        if abs(got - share) <= 0.03:
            grp = waists[:cut] if length == lengths[0] else waists[cut:]
            best = f"W{grp[0]}-{grp[-1]}"
            break
    return best


# ======================================================================== output
def write(res, out_path):
    bom, rows = res["bom"], res["rows"]
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "New (Filled)"
    help_h = ["Source of filled values", "PO / CBD description", "Notes", "Orig BOM row"]
    for i, h in enumerate(bom.head + help_h, 1):
        c = ws.cell(1, i, h)
        c.font = Font(name="Calibri", size=11, bold=True)
        c.fill = PatternFill("solid", fgColor="FFFF00") if i <= 20 else PatternFill("solid", fgColor="D9D9D9")
        c.alignment = Alignment(wrap_text=True, vertical="center")
    log = []
    for rr, row in enumerate(rows, 2):
        srow = row.orig if isinstance(row.orig, int) else bom.rows[-1]
        for i, v in enumerate(row.vals):
            c = ws.cell(rr, i + 1, v)
            sc = bom.ws.cell(srow, i + 1)
            c.font, c.alignment, c.number_format = copy.copy(sc.font), copy.copy(sc.alignment), sc.number_format
            if i in row.st:
                kind, note, old, source = row.st[i]
                if kind == "NOMATCH":
                    c.fill = YELLOW
                    c.comment = Comment(f"NOT MATCHED: {note}", "BOM tool")
                    log.append([f"{COLS[i]}{rr}", row.orig, bom.head[i], old, "NO PO", "", "", note])
                    continue
                c.fill = KIND_FILL[kind]
                head = {"UPDATE": f"UPDATED (was {old!r})"}.get(kind, KIND_TEXT[kind])
                c.comment = Comment(f"{head}: {note}\nSource: {source}", "BOM tool")
                c.comment.width, c.comment.height = 360, 160
                log.append([f"{COLS[i]}{rr}", row.orig, bom.head[i], old, KIND_TEXT[kind], v if kind != "CHECK" else "", source, note])
        helper = ["; ".join(dict.fromkeys(row.src)), row.po_desc, " | ".join(dict.fromkeys(row.notes)), row.orig]
        for k, v in enumerate(helper):
            c = ws.cell(rr, 21 + k, v)
            c.font = Font(name="Calibri", size=9, italic=True)
            c.alignment = Alignment(wrap_text=True, vertical="top")
            c.fill = PURPLE if row.added else GREY
    widths = [13, 10, 22, 19, 12, 16, 14, 26, 16, 20, 19, 18, 50, 19, 15, 11, 18, 10, 11, 16, 34, 46, 46, 9]
    for k, w in enumerate(widths, 1):
        ws.column_dimensions[openpyxl.utils.get_column_letter(k)].width = w
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:X{len(rows) + 1}"

    lg = wb.create_sheet("Change Log")
    lg.append([f"BOM auto-fill | CBD file {res['cbd']['header'].get('File Nos', '')} | {len(res['pos'])} POs, {len(res['items'])} PO items"])
    lg.append(["Green = filled from the PO (season/consumption from the CBD). Peach = CBD budget price, or inferred/copied: confirm. Blue = updated (old value in col D). Orange = check. Yellow = no PO for this BOM row."])
    lg.append([])
    hd = ["Cell", "Orig BOM row", "Field", "Old value", "Action", "New / source value", "Source", "Note"]
    lg.append(hd)
    order = {"FILLED": 0, "CBD/INFERRED": 1, "UPDATED": 2, "FILLED+CHECK": 3, "CHECK": 4, "NO PO": 5}
    for x in sorted(log, key=lambda x: (order.get(x[4], 9))):
        lg.append(x)
    for i in range(1, 9):
        lg.cell(4, i).font, lg.cell(4, i).fill = Font(bold=True, color="FFFFFF"), HDR
    fillmap = {"FILLED": GREEN, "CBD/INFERRED": PEACH, "UPDATED": BLUE, "FILLED+CHECK": ORANGE, "CHECK": ORANGE, "NO PO": YELLOW}
    for r_ in range(5, lg.max_row + 1):
        lg.cell(r_, 5).fill = fillmap.get(lg.cell(r_, 5).value, YELLOW)
        for i in range(1, 9):
            lg.cell(r_, i).alignment = Alignment(wrap_text=True, vertical="top")
    lg["A1"].font = Font(bold=True, size=12)
    for k, w in enumerate([9, 9, 20, 26, 13, 28, 36, 70], 1):
        lg.column_dimensions[openpyxl.utils.get_column_letter(k)].width = w
    lg.freeze_panes = "A5"

    pl = wb.create_sheet("PO Lines")
    pl.append(["PO No", "PDF page", "Supplier", "PO type", "Currency", "Item", "Category", "Description", "Line spec",
               "Qty", "UOM", "Unit price", "Amount", "Used?"])
    for it in res["items"]:
        for l in it["lines"]:
            pl.append([it["po"]["po_no"], l["page"], it["po"]["supplier"], it["po"]["type"], it["po"]["currency"], it["item_no"],
                       it["cat"], it["desc"], l["spec"], l["qty"], l["uom"], l["price"], l["amount"],
                       "Yes" if it["key"] in res["used"] else "Extra row (not in BOM)"])
    for i in range(1, 15):
        pl.cell(1, i).font, pl.cell(1, i).fill = Font(bold=True, color="FFFFFF"), HDR
    for r_ in range(2, pl.max_row + 1):
        if pl.cell(r_, 14).value != "Yes":
            pl.cell(r_, 14).fill = ORANGE
    for k, w in enumerate([12, 7, 30, 9, 8, 5, 12, 55, 40, 10, 11, 10, 11, 18], 1):
        pl.column_dimensions[openpyxl.utils.get_column_letter(k)].width = w
    pl.freeze_panes = "A2"
    pl.auto_filter.ref = f"A1:N{pl.max_row}"

    cb = wb.create_sheet("CBD Data")
    for k, v in res["cbd"]["header"].items():
        cb.append([k, v])
    for bi, blk in enumerate(res["cbd"]["blocks"], 1):
        cb.append([])
        cb.append([f"Costing block {bi}: {', '.join(blk['colours'])}"])
        cb.cell(cb.max_row, 1).font = Font(bold=True)
        cb.append(["Fabric type", "Supplier", "Fabrication", "Ref code", "Cons yds/dz", "YY per pc", "Price/yd", "CBD row"])
        for f in blk["fabrics"]:
            cb.append([f["type"], f["supplier"], f["fabrication"], f["ref"], f["cons"], round(f["cons"] / 12, 4) if f["cons"] else None,
                       f["price"], f["row"]])
        cb.append(["Cost type", "Remarks", "USD per dz", "USD per pc", "CBD row"])
        for o in blk["others"]:
            cb.append([o["type"], o["remarks"], o["cost"], round(o["cost"] / 12, 5) if o["cost"] else None, o["row"]])
    for k, w in enumerate([24, 30, 60, 22, 12, 12, 10, 9], 1):
        cb.column_dimensions[openpyxl.utils.get_column_letter(k)].width = w

    ck = wb.create_sheet("Checks")
    ck.append(["Self-checks. Every line must say OK. A FAIL means part of a file was not read correctly: do not trust the run."])
    ck["A1"].font = Font(bold=True)
    ck.append([])
    ck.append(["PO no", "Page", "Supplier", "Item", "Description", "Lines", "Printed qty", "Read qty", "Printed amount", "Read amount", "Result"])
    for x in res["po_rows"]:
        ck.append(x)
    ck.append([])
    ck.append(["CBD check", "Printed", "Calculated", "Result"])
    for x in res["cbd"]["checks"]:
        ck.append(x)
    ck.append([])
    ck.append(["Garment colour mapping (BOM colour -> PO colour labels)"] + [f"{k} -> {', '.join(v) or 'NOT FOUND'}" for k, v in res["gmap"].items()])
    ck.append([])
    ck.append(["WARNINGS"] + ([] if res["warnings"] else ["none"]))
    for w in res["warnings"]:
        ck.append(["", w])
        ck.cell(ck.max_row, 2).fill = ORANGE
    for r_ in range(1, ck.max_row + 1):
        for c_ in range(1, 12):
            v = ck.cell(r_, c_).value
            if v == "OK":
                ck.cell(r_, c_).fill = GREEN
            elif v == "FAIL":
                ck.cell(r_, c_).fill = ORANGE
    for k, w in enumerate([22, 8, 30, 12, 50, 7, 12, 12, 14, 14, 8], 1):
        ck.column_dimensions[openpyxl.utils.get_column_letter(k)].width = w
    wb.save(out_path)
    return log


def run(bom_path, cbd_path, pdf_path, out=None, update=False, force=False):
    res = build(bom_path, cbd_path, pdf_path, update)
    cbd, pos = res["cbd"], res["pos"]
    pdf_files = {p["file_no"] for p in pos if p["file_no"]}
    style = re.match(r"\s*(\d{5,})", str(res["bom"].ws.cell(res["bom"].rows[0], 3).value or ""))
    problems = []
    if cbd["header"].get("File Nos") and pdf_files and cbd["header"]["File Nos"] not in pdf_files:
        problems.append(f"CBD file {cbd['header']['File Nos']} is not in the PO PDF files {sorted(pdf_files)}")
    if style and style.group(1) not in (cbd["header"].get("Style Desc.", "") + " ".join(s for s, _, _ in cbd["styles"])):
        problems.append(f"BOM style {style.group(1)} not found in CBD ({cbd['header'].get('Style Desc.')})")
    if problems and not force:
        raise SystemExit("STOPPED, files do not belong together:\n  " + "\n  ".join(problems) + "\nUse force=True only if you are sure.")
    out = out or f"BOM_FILLED_{cbd['header'].get('File Nos') or 'output'}.xlsx"
    log = write(res, out)
    cnt = Counter(x[4] for x in log)
    cbd_ok = all(c[-1] == "OK" for c in cbd["checks"])
    print(f"POs: {len(pos)} | PO items: {len(res['items'])} | PO lines: {sum(len(i['lines']) for i in res['items'])} | "
          f"PO totals check: {'ALL OK' if res['po_ok'] else 'FAIL - see Checks sheet'}")
    print(f"CBD blocks: {len(cbd['blocks'])} ({'; '.join(', '.join(b['colours']) for b in cbd['blocks'])}) | CBD check: {'ALL OK' if cbd_ok else 'FAIL - see Checks sheet'}")
    print(f"BOM rows in: {len(res['bom'].rows)} | rows out: {len(res['rows'])} | " + ", ".join(f"{k}: {v}" for k, v in cnt.items()))
    print(f"PO items not in BOM (extra rows added): {len(res['unused'])}")
    if res["warnings"]:
        print("WARNINGS (also on the Checks sheet):")
        for w in res["warnings"]:
            print("  -", w)
    if res["failed_pos"]:
        print(f"!! PO self-check FAILED for {sorted(res['failed_pos'])}: values from these POs are marked orange. Check the Checks sheet.")
    print("Saved:", out)
    return out


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="Fill a BOM 'New' tab from the PO PDF + CBD")
    ap.add_argument("bom"); ap.add_argument("cbd"); ap.add_argument("pdf")
    ap.add_argument("--out"); ap.add_argument("--update", action="store_true", help="overwrite BOM values that disagree with the PO")
    ap.add_argument("--force", action="store_true")
    a = ap.parse_args()
    run(a.bom, a.cbd, a.pdf, a.out, a.update, a.force)

