"""Browser wrapper around bom_tool.run (runs inside Pyodide)."""
import sys, io, os, json, traceback

WORK = "/work"


def _ext(data, fallback):
    head = bytes(data[:8])
    if head.startswith(b"PK"):
        return ".xlsx"
    if head.startswith(b"\xd0\xcf\x11\xe0"):
        return ".xls"
    if head.startswith(b"%PDF"):
        return ".pdf"
    return fallback


def _save(data, base, fallback):
    ext = _ext(data, fallback)
    path = os.path.join(WORK, base + ext)
    with open(path, "wb") as f:
        f.write(bytes(data))
    return path, ext


def _colour(cell):
    try:
        f = cell.fill
        if f is None or f.fill_type != "solid":
            return None
        rgb = f.fgColor.rgb
        if isinstance(rgb, str) and len(rgb) >= 6:
            return "#" + rgb[-6:]
    except Exception:
        pass
    return None


def _txt(v):
    if v is None:
        return ""
    if isinstance(v, float):
        return ("%.6f" % v).rstrip("0").rstrip(".")
    return str(v)


def _preview(out_path):
    import openpyxl
    wb = openpyxl.load_workbook(out_path)
    ws = wb["New (Filled)"]
    rows = []
    for r in range(1, ws.max_row + 1):
        row = []
        for c in range(1, min(ws.max_column, 24) + 1):
            cell = ws.cell(r, c)
            note = cell.comment.text if cell.comment else ""
            row.append([_txt(cell.value), _colour(cell) if r > 1 else None, note])
        rows.append(row)
    checks = []
    if "Checks" in wb.sheetnames:
        for row in wb["Checks"].iter_rows(values_only=True):
            vals = [_txt(v) for v in row if v is not None]
            if vals:
                checks.append(vals)
    return rows, checks


_PDF = {"path": None, "pdf": None}


def open_pdf(pdf_in):
    """Open the PO PDF once (per worker). Returns the page count."""
    import pdfplumber
    if _PDF["pdf"] is not None:
        try:
            _PDF["pdf"].close()
        except Exception:
            pass
    _PDF["pdf"] = pdfplumber.open(pdf_in)
    _PDF["path"] = pdf_in
    return len(_PDF["pdf"].pages)


def extract_one(pno):
    """Text of one page (1-based) exactly as bom_tool.parse_po reads it. Returns JSON [text, n_images]."""
    page = _PDF["pdf"].pages[int(pno) - 1]
    text = page.extract_text() or ""
    nimg = 0
    if not text.strip():
        try:
            nimg = len(page.images or [])
        except Exception:
            nimg = 0
    page.close()
    return json.dumps([text, nimg])


class _ShimPage:
    def __init__(self, text, nimg):
        self._text = text
        self.images = [None] * int(nimg)

    def extract_text(self):
        return self._text


class _ShimPDF:
    def __init__(self, pages):
        self.pages = pages

    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False


class _ShimPlumber:
    """Stands in for pdfplumber inside bom_tool when the page texts were read in parallel workers."""
    def __init__(self, pages):
        self._pages = pages

    def open(self, *a, **k):
        return _ShimPDF([_ShimPage(t, n) for t, n in self._pages])


def go(bom_in, cbd_in, pdf_in, force=False, pages_json=None):
    """Paths of the 3 uploaded files (written by JS). Returns a JSON string."""
    with open(bom_in, "rb") as f:
        bom = f.read()
    with open(cbd_in, "rb") as f:
        cbd = f.read()
    with open(pdf_in, "rb") as f:
        pdf = f.read()
    os.makedirs(WORK, exist_ok=True)
    for f in os.listdir(WORK):
        try:
            os.remove(os.path.join(WORK, f))
        except OSError:
            pass
    res = {"status": "error", "log": "", "message": "", "rows": [], "checks": []}
    bad = []
    bom_p, e1 = _save(bom, "bom", ".xlsx")
    cbd_p, e2 = _save(cbd, "cbd", ".xls")
    pdf_p, e3 = _save(pdf, "po", ".pdf")
    if e1 != ".xlsx":
        bad.append("The BOM file is not an Excel .xlsx file.")
    if e2 not in (".xls", ".xlsx"):
        bad.append("The CBD file is not an Excel .xls or .xlsx file.")
    if e3 != ".pdf":
        bad.append("The PO file is not a PDF.")
    if bad:
        res["message"] = " ".join(bad) + " Please check that each file is in the right box."
        return json.dumps(res)
    out_p = os.path.join(WORK, "out.xlsx")
    buf = io.StringIO()
    old = sys.stdout
    sys.stdout = buf
    import bom_tool
    real = bom_tool.pdfplumber
    try:
        if pages_json:
            data = json.loads(pages_json)
            bom_tool.pdfplumber = _ShimPlumber([data[str(i)] for i in range(1, len(data) + 1)])
        bom_tool.run(bom_p, cbd_p, pdf_p, out=out_p, force=bool(force))
        res["status"] = "ok"
    except SystemExit as e:
        res["status"] = "stopped"
        res["message"] = str(e).replace("Use force=True only if you are sure.", "").strip()
    except Exception as e:
        res["status"] = "error"
        res["message"] = f"{type(e).__name__}: {e}"
        res["trace"] = traceback.format_exc()[-3000:]
    finally:
        sys.stdout = old
        bom_tool.pdfplumber = real
    res["log"] = buf.getvalue()
    if res["status"] == "ok":
        try:
            res["rows"], res["checks"] = _preview(out_p)
        except Exception as e:
            res["log"] += f"\n(preview failed: {e})"
    return json.dumps(res)


def output_bytes():
    with open(os.path.join(WORK, "out.xlsx"), "rb") as f:
        return f.read()
